"""Reel A04 · serie arranques (fuentes en guiones_arr.py)."""
TIT = ('EL CONTACTOR DE 32 A', 'QUE NO AGUANTA 10 HP')
GUION = {'gancho': 'Mi motor consume veintiséis punto cinco amperios y el contactor dice treinta y dos. Sobra, ¿no? Pues para un motor de diez caballos a doscientos ocho voltios, se queda corto.', 'p1': 'La corriente de un contactor siempre va con su categoría de empleo, de la I E C sesenta mil novecientos cuarenta y siete cuatro uno. A C uno es para cargas resistivas, como hornos y calefacción. A C tres es para motores de jaula de ardilla: arrancar y desconectar con el motor en marcha.', 'p2': 'En A C tres el contacto cierra con la corriente de arranque, seis a ocho veces la nominal, y además abre con arco. Por eso el mismo aparato tiene una corriente A C tres menor que la A C uno.', 'p3': 'Para motores, el fabricante da además una tabla de caballos por tensión. En un catálogo típico, el contactor de treinta y dos amperios llega a siete punto cinco caballos a doscientos ocho voltios. El de treinta y ocho amperios, a diez caballos.', 'p4': 'La razón: a doscientos ocho voltios, la corriente de tabla de un motor de diez caballos es treinta punto ocho amperios, más que la de placa. El contactor se elige con la tabla de caballos o con la corriente A C tres, nunca con la corriente A C uno.', 'p5': 'Así que en el tablero va un contactor de treinta y ocho amperios en A C tres, con bobina de ciento veinte voltios, un contacto auxiliar normalmente abierto y uno cerrado.', 'cierre': 'Si te sirvió, suscríbete y sígueme.'}
